source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (1, 2, 3, 6):
                points[grid[r][c]] = (r, c)

    lines = {}
    if 1 in points:
        r, c = points[1]
        end = (r - 1, c + 2)
        path = [(r, c + 1), (r, c + 2)]
        for rr, cc in path:
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = 5
        if 0 <= end[0] < h and 0 <= end[1] < w:
            out[end[0]][end[1]] = 1

    if 2 in points:
        r, c = points[2]
        lo, hi = sorted((c, c - 4))
        lines[2] = {(r, cc) for cc in range(lo, hi + 1)}
        for rr, cc in lines[2]:
            if (rr, cc) != (r, c):
                out[rr][cc] = 5
        endc = c - 4
        if 0 <= endc < w:
            out[r][endc] = 2

    for color, dr in ((3, 3), (6, -6)):
        if color not in points:
            continue
        r, c = points[color]
        endr = r + dr
        lo, hi = sorted((r, endr))
        lines[color] = {(rr, c) for rr in range(lo, hi + 1)}
        for rr in range(lo, hi + 1):
            if (rr, c) != (r, c):
                out[rr][c] = 5
        if 0 <= endr < h:
            out[endr][c] = color

    if 2 in lines:
        for color in (3, 6):
            for r, c in lines.get(color, set()):
                if (r, c) in lines[2]:
                    out[r][c] = 4
                    rr, cc = r + 1, c - 1
                    while 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 4
                        rr += 1
                        cc -= 1
    return out
